[Fact]
public void WorkflowAndPlcStageEnumsRemainSeparate()
{
    Assert.Equal(
        [WholeTrayWorkflowStage.Detection, WholeTrayWorkflowStage.Sorting,
         WholeTrayWorkflowStage.UnloadPreparation, WholeTrayWorkflowStage.UnlockObservation,
         WholeTrayWorkflowStage.ManualTrayRemovalConfirmation],
        Enum.GetValues<WholeTrayWorkflowStage>());
    Assert.Equal(
        [PlcWorkflowStage.Sorting, PlcWorkflowStage.UnloadPreparation,
         PlcWorkflowStage.UnlockObservation],
        Enum.GetValues<PlcWorkflowStage>());
    Assert.NotEqual(typeof(WholeTrayWorkflowStage), typeof(PlcWorkflowStage));
}

[Fact]
public async Task SortingMotionCannotConsumeTheLongerTrayDeadline()
{
    var wire = new ScriptedTransport(new ushort[] { 0, 0 }.Concat(Enumerable.Repeat((ushort)1, 10000)));
    var adapter = new LatestProtocolStageActionAdapter(wire, () => Observation(9), 80, 40,
        pollMs: 5, sortingPickCommit: (_, _, _) => Task.CompletedTask);
    var result = await adapter.ExecuteAsync(Request(PlcWorkflowStage.Sorting), default);
    Assert.True(result.IsUnknownHeld);
    Assert.Equal("PlcStageDeadlineExceeded", result.ErrorCode);
    Assert.DoesNotContain(wire.Writes, x => x == (0x20, 2));
    Assert.DoesNotContain(wire.Writes, x => x.Offset == 0x53);
}

[Fact]
public async Task SortingPickPlaceAckRequiresStatusThreeBeforeCompletion()
{
    var wire = new ScriptedTransport([0, 0, 1, 2, 1, 3, 0]);
    var adapter = Adapter(wire);

    var result = await adapter.ExecuteAsync(Request(PlcWorkflowStage.Sorting, part: 7), default);

    Assert.True(result.IsCompleted);
    Assert.Equal((ushort)3, result.ProtocolStatus);
    Assert.Equal([(0x20, 1), (0x20, 0), (0x1F, 7), (0x20, 2),
        (0x20, 0), (0x53, 1), (0x53, 0)], wire.Writes);
    Assert.Equal([0x02, 0x04, 0x0A, 0x02, 0x04, 0x0A], wire.PositionWrites);
    Assert.Contains(0x0C, wire.ReadOffsets);
    Assert.Contains(0x0E, wire.ReadOffsets);
    Assert.Contains(0x10, wire.ReadOffsets);
}

[Fact]
public async Task SortingLatchesTargetStageBeforeRaisedCompletionZ()
{
    var wire = new ScriptedTransport([0, 0, 1, 2, 1, 3, 0]) { RaiseOnCompletion = true };
    var result = await Adapter(wire).ExecuteAsync(Request(PlcWorkflowStage.Sorting), default);
    Assert.True(result.IsCompleted);
    Assert.Contains((0x1F, 1), wire.Writes);
    Assert.Contains((0x53, 0), wire.Writes);
    var target = Assert.Single(result.PositionEvidence, x => x.Phase == "PickTargetObserved");
    var completed = Assert.Single(result.PositionEvidence, x => x.Phase == "PickCompleted");
    Assert.True(target.Matched);
    Assert.NotEqual(target.ActualZ, completed.ActualZ);
    Assert.Equal("GrabZ", target.AxisRole);
}

[Fact]
public async Task PickMustBeSavedBeforePlaceFieldsAndSaveFailureKeepsUnknownHold()
{
    var wire = new ScriptedTransport([0, 0, 1, 2, 1, 3, 0]);
    var saved = false;
    var adapter = new LatestProtocolStageActionAdapter(wire, () => Observation(9), 8000, 2000, pollMs: 1,
        delay: (_, _) => Task.CompletedTask, sortingPickCommit: (_, evidence, _) =>
        {
            Assert.Contains(evidence, x => x.Phase == "PickCompleted");
            Assert.DoesNotContain(wire.Writes, x => x.Offset == 0x1F || x == (0x20, 2));
            Assert.Equal(3, wire.PositionWrites.Count);
            saved = true;
            throw new InvalidOperationException("ControlledSortingPickSaveFailure");
        });
    var result = await adapter.ExecuteAsync(Request(PlcWorkflowStage.Sorting), default);
    Assert.True(saved);
    Assert.True(result.IsUnknownHeld);
    Assert.False(result.CanRetry);
    Assert.DoesNotContain(wire.Writes, x => x.Offset == 0x1F || x == (0x20, 2) || x.Offset == 0x53);
}

