[Fact]
public async Task UnloadWritesGrabZAndConfirmsFreshXyzArrival()
{
    var wire = new UnloadTransport { CompleteOnCommand = true };
    var result = await Adapter(wire).ExecuteAsync(Request(PlcWorkflowStage.UnloadPreparation), default);

    Assert.True(result.IsCompleted);
    Assert.Equal((ushort)1, result.ProtocolStatus);
    Assert.Equal([0x02, 0x04, 0x0A], wire.TargetWriteOffsets);
    Assert.Equal([(0x00, 4), (0x00, 0)], wire.CommandWrites);
    Assert.True(wire.LastTargetWriteSequence < wire.CommandSequence);
    Assert.Equal((ushort)1, wire.XyStatus);
}

