[Fact]
public async Task UnlockRequiresCommittedWholeTrayReferenceAndObservesZero()
{
    var wire = new ScriptedTransport([1, 1, 0]);
    var result = await Adapter(wire).ExecuteAsync(Request(PlcWorkflowStage.UnlockObservation), default);

    Assert.True(result.IsCompleted);
    Assert.Equal((ushort)0, result.ProtocolStatus);
