[Fact]
public async Task DisconnectAfterCommandWriteIsUnknownHeldAndCommandIsNeverReplayed()
{
    var held = new List<string>();
    var wire = new ScriptedTransport([0]) { FailReadsAfterWrite = true };
    var result = await Adapter(wire, held.Add).ExecuteAsync(
        Request(PlcWorkflowStage.Sorting, part: 3), default);

    Assert.True(result.IsUnknownHeld);
    Assert.Single(held);
    Assert.Equal(1, wire.Writes.Count(x => x == (0x20, 1)));
    Assert.Equal([(0x20, 1)], wire.Writes);
}

[Fact]
public async Task PredispatchCommunicationUsesFourTotalAttemptsAndOneTwoFourBackoff()
{
    var waits = new List<TimeSpan>();
    var wire = new ScriptedTransport([]) { RemainingReadFailures = 4 };
    var adapter = Adapter(wire, delay: (value, _) => { waits.Add(value); return Task.CompletedTask; });

    var result = await adapter.ExecuteAsync(Request(PlcWorkflowStage.UnloadPreparation), default);

    Assert.Equal(StageActionKind.Failed, result.Kind);
    Assert.False(result.HoldsDevice);
    Assert.Empty(wire.Writes);
    Assert.Equal(4, wire.ReadAttempts);
    Assert.Equal([TimeSpan.FromSeconds(1), TimeSpan.FromSeconds(2), TimeSpan.FromSeconds(4)], waits);
}

[Fact]
public async Task EpochChangeAfterDispatchIsUnknownAndNeverReplaysPhysicalAction()
{
    var epoch = 9L;
    var wire = new UnloadTransport { CompleteOnCommand = true, AfterCommand = () => epoch++ };
    var adapter = new LatestProtocolStageActionAdapter(wire, () => Observation(epoch), 8000, 2000,
        pollMs: 1, delay: (_, _) => Task.CompletedTask);

    var result = await adapter.ExecuteAsync(Request(PlcWorkflowStage.UnloadPreparation, epoch: 9), default);

    Assert.True(result.IsUnknownHeld);
    Assert.Equal(1, wire.CommandWrites.Count(x => x == (0x00, 4)));
}

[Theory]
[InlineData(HostOrder.Abcd, SimOrder.ABCD, 0x42F6, 0xE979)]
[InlineData(HostOrder.Cdab, SimOrder.CDAB, 0xE979, 0x42F6)]
[InlineData(HostOrder.Badc, SimOrder.BADC, 0xF642, 0x79E9)]
[InlineData(HostOrder.Dcba, SimOrder.DCBA, 0x79E9, 0xF642)]
public void KnownFloatHasExpectedWireWordsAndBothSidesAgree(HostOrder host, SimOrder sim, int a, int b)
{
    ushort[] expected = [(ushort)a, (ushort)b];
    Assert.Equal(expected, ProtocolLatestFloat32.Encode(123.456f, host));
    Assert.Equal(expected, Float32Codec.Encode(123.456f, sim));
    Assert.Equal(123.456f, ProtocolLatestFloat32.Decode(expected[0], expected[1], host));
    Assert.Equal(123.456f, Float32Codec.Decode(expected[0], expected[1], sim));
    foreach (var value in new[] { 0f, -0.125f, -100.5f, 100f, 150f, 65536.25f })
    {
        var words = ProtocolLatestFloat32.Encode(value, host);
        Assert.Equal(value, Float32Codec.Decode(words[0], words[1], sim));
    }
}

[Fact]
public void AddressesDirectionsAndWidthsMatchLatestDocument()
{
    Assert.Equal(ProtocolLatestMap.Contract, PlcAddressMap.Contract);
    var pcCoils = new[] { 2, 3, 6, 7, 9, 0x11, 0x20, 0x21 };
    var plcCoils = new[] { 1, 4, 5, 8, 0x10 };
    foreach (var point in pcCoils.Concat(plcCoils))
    {
        var entry = PlcAddressMap.CoilPoints[point];
        Assert.Equal(pcCoils.Contains(point) ? PlcDirection.PcToPlc : PlcDirection.PlcToPc, entry.Direction);
        Assert.Equal(PlcValueType.Bool, entry.ValueType);
        Assert.Equal(point - 1, PlcAddressMap.ToPduOffset(point));
    }
    var floats = new[] { 3, 5, 7, 9, 0xB, 0xD, 0xF, 0x11, 0x31, 0x33, 0x35 };
    foreach (var point in floats)
    {
        var entry = PlcAddressMap.HoldingRegisterPoints[point];
        Assert.Equal(PlcValueType.Float32, entry.ValueType);
        Assert.Equal(2, entry.RegisterCount);
        Assert.Same(entry, PlcAddressMap.RegisterAt(point + 1));
    }
    var points = new (ushort Host, int Plc)[] {
        (ProtocolLatestMap.CameraTargetX,3),(ProtocolLatestMap.CameraTargetY,5),
        (ProtocolLatestMap.CameraTargetZ,7),(ProtocolLatestMap.ScanTargetZ,9),
        (ProtocolLatestMap.GrabTargetZ,0xB),(ProtocolLatestMap.CurrentX,0xD),
        (ProtocolLatestMap.CurrentY,0xF),(ProtocolLatestMap.CurrentZ,0x11),
        (ProtocolLatestMap.ZMoveStatus,0x13),(ProtocolLatestMap.RecipeId,0x40),
        (ProtocolLatestMap.AlarmBits,0x50),(ProtocolLatestMap.AlarmSeverity,0x51),
        (ProtocolLatestMap.InspectionStatus,0x52),(ProtocolLatestMap.ZResetStatus,0x53) };
    foreach (var (host, plc) in points) Assert.Equal(plc - 1, ProtocolLatestMap.Offset(host));
    Assert.Equal(PlcDirection.PcToPlc, PlcAddressMap.HoldingRegisterPoints[0x52].Direction);
    Assert.Equal(PlcDirection.PlcToPc, PlcAddressMap.HoldingRegisterPoints[0x53].Direction);
    Assert.Equal(PlcValueType.Int16, PlcAddressMap.HoldingRegisterPoints[0x40].ValueType);
}

[Fact]
public void OwnershipAndWholeFloatWritesAreEnforced()
{
    var store = new PlcDataStore(Microsoft.Extensions.Options.Options.Create(new SimulationOptions()));
    Assert.False(store.TryWriteHoldingRegistersFromPc(0x52, [2])); // PLC-owned reset
    Assert.False(store.TryWriteHoldingRegistersFromPc(2, [100])); // half a Float32
    Assert.False(store.TryWriteCoilsFromPc(0, [true])); // PLC-owned heartbeat
    Assert.Throws<InvalidOperationException>(() => store.SetCoilFromPlc(9, true));
    Assert.Throws<InvalidOperationException>(() => store.SetHoldingRegisterFromPlc(0x52, 1));
    Assert.True(store.TryWriteHoldingRegistersFromPc(0x51, [1]));
}

[Fact]
public void PalletLockCommandAndStatusHaveOppositeOwnership()
{
    Assert.Equal(PlcDirection.PcToPlc,
        PlcAddressMap.HoldingRegisterPoints[PlcAddressMap.HoldingRegisters.PalletLockCmd].Direction);
    Assert.Equal(PlcDirection.PlcToPc,
        PlcAddressMap.HoldingRegisterPoints[PlcAddressMap.HoldingRegisters.PalletLockStatus].Direction);
    var store = new PlcDataStore(Microsoft.Extensions.Options.Options.Create(new SimulationOptions()));
    Assert.False(store.TryWriteHoldingRegistersFromPc(
        PlcAddressMap.ToPduOffset(PlcAddressMap.HoldingRegisters.PalletLockStatus), [1]));
    Assert.True(store.TryWriteHoldingRegistersFromPc(
        PlcAddressMap.ToPduOffset(PlcAddressMap.HoldingRegisters.PalletLockCmd), [0]));
    Assert.False(store.TryWriteHoldingRegistersFromPc(
        PlcAddressMap.ToPduOffset(PlcAddressMap.HoldingRegisters.PalletLockCmd), [1]));
}

[Fact]
public void FStatusCannotBeClearedBeforeCompletionEvenWithStaleResetTwo()
{
    var store = new PlcDataStore(Options.Create(new SimulationOptions()));
    var status = PlcAddressMap.ToPduOffset(PlcAddressMap.HoldingRegisters.InspectionStatus);
    Assert.True(store.TryWriteHoldingRegistersFromPc(status, [(ushort)3]));
    store.SetHoldingRegisterFromPlc(PlcAddressMap.HoldingRegisters.ZResetStatus, 2);
    Assert.False(store.TryWriteHoldingRegistersFromPc(status, [(ushort)0]));
    Assert.Equal((ushort)3, store.ReadHoldingRegisterByDocumentNumber(
        PlcAddressMap.HoldingRegisters.InspectionStatus));
    Assert.True(store.TryWriteHoldingRegistersFromPc(status, [(ushort)4]));
    store.SetHoldingRegisterFromPlc(PlcAddressMap.HoldingRegisters.ZResetStatus, 3);
    Assert.False(store.TryWriteHoldingRegistersFromPc(status, [(ushort)0]));
}

[Fact]
public async Task FormalHostPortObservesConnectionEpochChangeWhenTcpServiceDisconnects()
{
    var port = FreePort();
    var simulation = new SimulationOptions
    {
        ScanPeriodMs = 2, HeartbeatPeriodMs = 20, HeartbeatTimeoutMs = 3000,
        MotionDurationMs = 10, SortingDurationMs = 10, PalletLockDurationMs = 10,
        ZoneConfigDurationMs = 8, InterActionGapMs = 2, ActionDurationJitterMs = 0
    };
    var store = new PlcDataStore(Options.Create(simulation));
    var engine = new VirtualPlcEngine(store, Options.Create(simulation),
        NullLogger<VirtualPlcEngine>.Instance);
    var server = new ModbusTcpServer(store, Options.Create(new ModbusOptions
    {
        ListenAddress = "127.0.0.1", Port = port, UnitId = 1
    }), NullLogger<ModbusTcpServer>.Instance);
    await engine.StartAsync(default);
    await server.StartAsync(default);
    await WaitForPortAsync(port);
    await using var device = new LatestProtocolPlcDevice(new PlcRuntimeOptions
    {
        Provider = "Virtual", Host = "127.0.0.1", Port = port, UnitId = 1,
        IoTimeoutMs = 100, PollMs = 5, HeartbeatTimeoutMs = 500
    }, 0.01);
    try
    {
        await device.StartAsync(default);
        await device.ResetAsync(default);
        await WaitAsync(() => Task.FromResult(device.Observe().Connected));
        var connectedEpoch = device.Observe().ConnectionEpoch;

        await server.StopAsync(default);
        await WaitAsync(() => Task.FromResult(
            !device.Observe().Connected && device.Observe().ConnectionEpoch > connectedEpoch));
        Assert.False(string.IsNullOrWhiteSpace(device.Failure));
    }
    finally
    {
        await engine.StopAsync(default);
        server.Dispose();
        engine.Dispose();
    }
}

[Fact]
public async Task HeartbeatFailureKeepsFirstCodeAndLastReliableObservationWhileBusinessPollContinues()
{
    var port = FreePort();
    var simulation = new SimulationOptions
    {
        ScanPeriodMs = 2, HeartbeatPeriodMs = 20, HeartbeatTimeoutMs = 3000
    };
    var store = new PlcDataStore(Options.Create(simulation));
    var engine = new VirtualPlcEngine(store, Options.Create(simulation),
        NullLogger<VirtualPlcEngine>.Instance);
    var server = new ModbusTcpServer(store, Options.Create(new ModbusOptions
    {
        ListenAddress = "127.0.0.1", Port = port, UnitId = 1
    }), NullLogger<ModbusTcpServer>.Instance);
    await engine.StartAsync(default);
    await server.StartAsync(default);
    await WaitForPortAsync(port);
    await using var device = new LatestProtocolPlcDevice(new PlcRuntimeOptions
    {
        Provider = "Virtual", Host = "127.0.0.1", Port = port, UnitId = 1,
        IoTimeoutMs = 100, PollMs = 5, HeartbeatTimeoutMs = 500
    }, 0.01);
    try
    {
        await device.StartAsync(default);
        await WaitAsync(() => Task.FromResult(device.Observe().Connected));
        engine.InjectFault(SimulationFault.PauseHeartbeat);
        await WaitAsync(() => Task.FromResult(device.Observe().DiagnosticCode == "PlcHeartbeatLost"));
        var first = device.Observe();
        await Task.Delay(100);
        var later = device.Observe();
        Assert.False(later.Connected);
        Assert.Equal("PlcHeartbeatLost", later.DiagnosticCode);
        Assert.Equal("heartbeat", later.FailureOrigin);
        Assert.Equal(first.ObservedUtc, later.ObservedUtc);
        Assert.True(later.ConnectionEpoch > 1);
    }
    finally
    {
        await engine.StopAsync(default);
        server.Dispose();
        engine.Dispose();
    }
}

[Fact]
public async Task StaleObservationNeverReusesOldSafetyClearAsCurrent()
{
    var port = FreePort();
    var simulation = new SimulationOptions { ScanPeriodMs = 2, HeartbeatPeriodMs = 20 };
    var store = new PlcDataStore(Options.Create(simulation));
    var engine = new VirtualPlcEngine(store, Options.Create(simulation),
        NullLogger<VirtualPlcEngine>.Instance);
    var server = new ModbusTcpServer(store, Options.Create(new ModbusOptions
    {
        ListenAddress = "127.0.0.1", Port = port, UnitId = 1
    }), NullLogger<ModbusTcpServer>.Instance);
    await engine.StartAsync(default);
    await server.StartAsync(default);
    await WaitForPortAsync(port);
    var device = new LatestProtocolPlcDevice(new PlcRuntimeOptions
    {
        Provider = "Virtual", Host = "127.0.0.1", Port = port, UnitId = 1,
        IoTimeoutMs = 100, PollMs = 5, HeartbeatTimeoutMs = 500
    }, 0.01);
    try
    {
        await device.StartAsync(default);
        await WaitAsync(() => Task.FromResult(device.Observe().Connected && device.Observe().SafetyClear));
        var lastReliable = device.Observe();
        await device.DisposeAsync(); // Ends polling without fabricating an unsafe PLC response.
        await Task.Delay(650);
        var stale = device.Observe();
        Assert.False(stale.Connected);
        Assert.False(stale.SafetyClear);
        Assert.Equal("PlcObservationStale", stale.DiagnosticCode);
        Assert.Equal("state-expiry", stale.FailureOrigin);
        Assert.Equal(lastReliable.ObservedUtc, stale.ObservedUtc);
    }
    finally
    {
        await device.DisposeAsync();
        await engine.StopAsync(default);
        server.Dispose();
        engine.Dispose();
    }
}

[Fact]
public async Task TcpProtocolExposesHeartbeatClampMoveSortUnloadUnlockAndFailureFacts()
{
    var port = FreePort();
    var simulation = new SimulationOptions
    {
        ScanPeriodMs = 2, HeartbeatPeriodMs = 20, HeartbeatTimeoutMs = 3000,
        MotionDurationMs = 12, SortingDurationMs = 12, PalletLockDurationMs = 12,
        ZoneConfigDurationMs = 8, InterActionGapMs = 4, ActionDurationJitterMs = 0,
        ZResetDurationMs = 8, ZResetTimeoutMs = 500, RandomSeed = 1
    };
    var store = new PlcDataStore(Options.Create(simulation));
    var engine = new VirtualPlcEngine(store, Options.Create(simulation),
        NullLogger<VirtualPlcEngine>.Instance);
    var server = new ModbusTcpServer(store, Options.Create(new ModbusOptions
    {
        ListenAddress = IPAddress.Loopback.ToString(), Port = port, UnitId = 1
    }), NullLogger<ModbusTcpServer>.Instance);
    await engine.StartAsync(default);
    await server.StartAsync(default);
    await WaitForPortAsync(port);
    await using var wire = new ModbusTcpClient("127.0.0.1", port, 1, TimeSpan.FromSeconds(1));
    await using var heartbeat = new ModbusTcpClient("127.0.0.1", port, 1, TimeSpan.FromSeconds(1));
    using var stop = new CancellationTokenSource();
    var echo = EchoHeartbeatAsync(heartbeat, stop.Token);
    try
    {
        await ChangedAsync(wire, O(ProtocolLatestMap.HeartbeatReq));
        await wire.WriteCoilAsync(O(ProtocolLatestMap.PcReady), true);

        await wire.WriteCoilAsync(O(ProtocolLatestMap.PcStart), true);
        await RegisterAsync(wire, ProtocolLatestMap.PalletLockStatus, 1);
        await wire.WriteCoilAsync(O(ProtocolLatestMap.PcStart), false);

        await wire.WriteRegistersAsync(O(ProtocolLatestMap.NgZoneCount), [15, 15]);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.ZoneConfigReady), 1);
        await RegisterAsync(wire, ProtocolLatestMap.ZoneConfigAck, 1);

        // Command 4 follows the completed inspection/Z-reset handshake and
        // performs a fresh XYZ move using Grab_Target_Z.
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetX, 11);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetY, 22);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetZ, 110);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.MoveCommand), 2);
        await RegisterAsync(wire, ProtocolLatestMap.XyPositionConfirmed, 1);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.MoveCommand), 0);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.InspectionStatus), 1);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.InspectionStatus), 2);
        await RegisterAsync(wire, ProtocolLatestMap.ZResetStatus, 2);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.InspectionStatus), 0);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetX, 11);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetY, 22);
        await WriteFloatAsync(wire, ProtocolLatestMap.GrabTargetZ, 150);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.MoveCommand), 4);
        await WaitAsync(async () => {
            var words = await wire.ReadRegistersAsync(O(ProtocolLatestMap.CurrentZ), 2);
            return ProtocolLatestFloat32.Decode(words[0], words[1],
                Gaode.Infrastructure.Devices.Plc.Float32ByteOrder.Abcd) == 150f;
        });
        await RegisterAsync(wire, ProtocolLatestMap.XyPositionConfirmed, 1);
        var actualZ = await wire.ReadRegistersAsync(O(ProtocolLatestMap.CurrentZ), 2);
        Assert.Equal(150f, ProtocolLatestFloat32.Decode(actualZ[0], actualZ[1],
            Gaode.Infrastructure.Devices.Plc.Float32ByteOrder.Abcd));
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.MoveCommand), 0);
        await RegisterAsync(wire, ProtocolLatestMap.XyPositionConfirmed, 1);

        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetX, 11);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetY, 22);
        await WriteFloatAsync(wire, ProtocolLatestMap.GrabTargetZ, 150);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortCommand), 1);
        await RegisterAsync(wire, ProtocolLatestMap.SortStatus, 2);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortCommand), 0);
        await Task.Delay(40);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortPartIndex), 3);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetX, 400);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetY, 300);
        await WriteFloatAsync(wire, ProtocolLatestMap.GrabTargetZ, 150);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortCommand), 2);
        await RegisterAsync(wire, ProtocolLatestMap.SortStatus, 3);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortCommand), 0);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortingOk), 1);
        await RegisterAsync(wire, ProtocolLatestMap.SortStatus, 0);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortingOk), 0);

        await wire.WriteRegisterAsync(O(ProtocolLatestMap.PalletLockCommand), 0);
        await RegisterAsync(wire, ProtocolLatestMap.PalletLockStatus, 0);

        await wire.WriteCoilAsync(O(ProtocolLatestMap.PcStart), true);
        await RegisterAsync(wire, ProtocolLatestMap.PalletLockStatus, 1);
        await wire.WriteCoilAsync(O(ProtocolLatestMap.PcStart), false);
        engine.InjectFault(SimulationFault.SortingFailure);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetX, 11);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetY, 22);
        await WriteFloatAsync(wire, ProtocolLatestMap.GrabTargetZ, 150);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortCommand), 1);
        await RegisterAsync(wire, ProtocolLatestMap.SortStatus, 4);

        // A TCP session ending never manufactures a stage/business completion. A fresh
        // Modbus session observes the last PLC-owned physical facts verbatim.
        await using (var disconnected = new ModbusTcpClient(
            "127.0.0.1", port, 1, TimeSpan.FromSeconds(1)))
            _ = await disconnected.ReadRegistersAsync(O(ProtocolLatestMap.SortStatus), 1);
        await using var reconnected = new ModbusTcpClient("127.0.0.1", port, 1, TimeSpan.FromSeconds(1));
        Assert.Equal((ushort)1, (await reconnected.ReadRegistersAsync(
            O(ProtocolLatestMap.PalletLockStatus), 1))[0]);
        Assert.Equal((ushort)4, (await reconnected.ReadRegistersAsync(
            O(ProtocolLatestMap.SortStatus), 1))[0]);
        await reconnected.WriteRegisterAsync(O(ProtocolLatestMap.SortCommand), 0);
    }
    finally
    {
        stop.Cancel();
        try { await echo; } catch (OperationCanceledException) { }
        await server.StopAsync(default);
        await engine.StopAsync(default);
        server.Dispose();
        engine.Dispose();
    }
}

