[Theory]
[InlineData(false)]
[InlineData(true)]
public async Task FormalHostPortKeepsPreviousArrivalUntilNextAcceptedMoveAndBindsAfterF(bool failFReset)
{
    var heartbeatLog = new BoundedTestLogger<LatestProtocolPlcDevice>();
    var port = FreePort();
    var simulation = new SimulationOptions
    {
        ScanPeriodMs = 2, HeartbeatPeriodMs = 100, HeartbeatTimeoutMs = 3000,
        MotionDurationMs = 180, ZResetDurationMs = 50, ZResetTimeoutMs = 1000,
        PalletLockDurationMs = 30, ZoneConfigDurationMs = 20,
        InterActionGapMs = 5, ActionDurationJitterMs = 0, RandomSeed = 61
    };
    var store = new PlcDataStore(Options.Create(simulation));
    var engine = new VirtualPlcEngine(store, Options.Create(simulation),
        NullLogger<VirtualPlcEngine>.Instance);
    var server = new ModbusTcpServer(store, Options.Create(new ModbusOptions
    {
        ListenAddress = "127.0.0.1", Port = port, UnitId = 1
    }), NullLogger<ModbusTcpServer>.Instance);
    await engine.StartAsync(default);
    await server.StartAsync(default);
    await WaitForPortAsync(port);
    await using var device = new LatestProtocolPlcDevice(new PlcRuntimeOptions
    {
        Provider = "Virtual", Host = "127.0.0.1", Port = port, UnitId = 1,
        IoTimeoutMs = 300, PollMs = 5, HeartbeatTimeoutMs = 2000,
        CommandClearHoldMs = 25
    }, 0.01, heartbeatLog);
    await using var observer = new ModbusTcpClient("127.0.0.1", port, 1, TimeSpan.FromSeconds(1));
    try
    {
        await device.StartAsync(default);
        await device.ResetAsync(default);
        await WaitAsync(() => Task.FromResult(device.Observe().Connected && device.Observe().SafetyClear));
        var runId = Guid.NewGuid();
        var start = Envelope(runId);
        await device.RequestStartAsync(start, Guid.NewGuid(), Guid.NewGuid(), _ => { }, default);
        try { await WaitAsync(() => Task.FromResult(device.Observe().PalletLockStatus == 1)); }
        catch
        {
            output.WriteLine(JsonSerializer.Serialize(new { device.Failure, observation = device.Observe(),
                startTrace = engine.GetStartTrace(),
                relevantChanges = store.GetChanges(0, 4096).Changes
                    .Where(x => x.Name is not ("PLC_Heartbeat_Req" or "PC_Heartbeat_Resp")).TakeLast(40) }));
            throw;
        }
        await device.PrepareZonesAsync(default);

        var first = new FixedPoint("3D", "1.0.0", 11, 22, "mm", "TEST", 33);
        await MoveAndInspectAsync(first, "3D");
        Assert.Equal((ushort)1, (await observer.ReadRegistersAsync(
            O(ProtocolLatestMap.XyPositionConfirmed), 1))[0]);
        Assert.Equal((ushort)2, (await observer.ReadRegistersAsync(
            O(ProtocolLatestMap.ZResetStatus), 1))[0]);

        var second = new FixedPoint("F", "1.0.0", 44, 55, "mm", "TEST", 66);
        await MoveAndInspectAsync(second, "F");
        if (failFReset)
        {
            var failedChanges = store.GetChanges(0, 4096).Changes;
            Assert.Contains(failedChanges, c => c.Name == "Inspection_Status" && c.Current == "4");
            Assert.Contains(failedChanges, c => c.Name == "Z_Reset_Status" && c.Current == "3");
            Assert.DoesNotContain(failedChanges.SkipWhile(c => c.Name != "Inspection_Status" || c.Current != "4"),
                c => c.Name == "Inspection_Status" && c.Current == "0");
            return;
        }
        using (var bindDeadline = new CancellationTokenSource(TimeSpan.FromSeconds(5)))
            await device.BindRecipeAsync(new PlcRecipeBinding(1, 15, 15), bindDeadline.Token);

        // Component-only injected Test target: this proves command 2 and the
        // inspection 1/2/reset handshake, not Q01 target admission.
        var detectionTarget = new FixedPoint("TEST-DETECTION-A", "1.0.0", 77, 88,
            "mm", "TEST", 99);
        await MoveAndInspectAsync(detectionTarget, "Detection");

        var changes = store.GetChanges(0, 4096).Changes;
        output.WriteLine("StartTrace=" + JsonSerializer.Serialize(engine.GetStartTrace()));
        AssertSubsequence(changes.Where(c => c.Name == "Inspection_Status").Select(c => c.Current),
            "1", "2", "0", "3", "4", "0", "1", "2", "0");
        AssertSubsequence(changes.Where(c => c.Name == "Z_Reset_Status").Select(c => c.Current),
            "1", "2", "0", "1", "2");
        AssertSubsequence(changes.Where(c => c.Name == "XY_Pos_Confirmed").Select(c => c.Current),
            "1", "0", "1");
        var nextCommand = changes.First(c => c.Name == "XY_Move_Cmd" && c.Current == "5");
        Assert.Contains(changes, c => c.Name == "Z_Reset_Status" && c.Current == "2" &&
            c.Sequence < nextCommand.Sequence);
        Assert.Contains(changes, c => c.Name == "Inspection_Status" && c.Current == "0" &&
            c.Sequence < nextCommand.Sequence);
        Assert.Contains(changes, c => c.Name == "XY_Pos_Confirmed" && c.Current == "0" &&
            c.Sequence > nextCommand.Sequence);
        Assert.Contains(changes, c => c.Name == "Z_Reset_Status" && c.Current == "0" &&
            c.Sequence > nextCommand.Sequence);
        Assert.Contains(changes, c => c.Name == "Z_Axis_Move_Status" && c.Current == "0" &&
            c.Sequence > nextCommand.Sequence);
        Assert.Contains(changes, c => c.Name == "Recipe_ID" && c.Current == "1");
        var relevant = changes.Where(c => c.Name is "XY_Move_Cmd" or "XY_Pos_Confirmed" or
            "Z_Axis_Move_Status" or "Inspection_Status" or "Z_Reset_Status" or "Recipe_ID").ToArray();
        var evidence = new { test = nameof(FormalHostPortKeepsPreviousArrivalUntilNextAcceptedMoveAndBindsAfterF),
            runId, port, source = "VirtualPlc over formal Modbus TCP", changes = relevant,
            rejectedWrites = store.GetWriteAudit().Where(w => !w.Accepted).ToArray() };
        var json = JsonSerializer.Serialize(evidence, new JsonSerializerOptions { WriteIndented = true });
        output.WriteLine(json);
        var root = Environment.GetEnvironmentVariable("GAODE_T061_EVIDENCE_ROOT");
        if (!string.IsNullOrWhiteSpace(root))
        {
            Directory.CreateDirectory(root);
            await File.WriteAllTextAsync(Path.Combine(root, "modbus-sequence.json"), json);
        }

        async Task MoveAndInspectAsync(FixedPoint target, string role)
        {
            var envelope = Envelope(runId);
            var completed = new TaskCompletionSource<DeviceEvent>(TaskCreationOptions.RunContinuationsAsynchronously);
            await device.RequestMoveAsync(new MoveRequest(envelope, Guid.NewGuid(), target,
                Guid.NewGuid(), "virtual-plc", role), e =>
                {
                    if (e.Kind == DeviceEventKind.Completed) completed.TrySetResult(e);
                    if (e.Kind is DeviceEventKind.Failed or DeviceEventKind.UnknownHeld)
                        completed.TrySetException(new IOException(e.ErrorCode ?? e.Kind.ToString()));
                }, default);
            DeviceEvent result;
            try { result = await completed.Task.WaitAsync(TimeSpan.FromSeconds(5)); }
            catch
            {
                output.WriteLine("MoveFailure=" + JsonSerializer.Serialize(new
                {
                    role, target, device.Failure, observation = device.Observe(),
                    heartbeatChanges = store.GetChanges(0, 4096).Changes
                        .Where(x => x.Name is "PLC_Heartbeat_Req" or "PC_Heartbeat_Resp" or "Alarm_Bits" or "PLC_Ready")
                        .TakeLast(100),
                    recentWrites = store.GetWriteAudit().TakeLast(100),
                    hostDiagnostics = heartbeatLog.Entries
                }));
                throw;
            }
            Assert.True(DeviceContract.Matches(result, envelope, device.Observe().ConnectionEpoch));
            Assert.InRange(device.Observe().X, target.X - 0.01, target.X + 0.01);
            Assert.InRange(device.Observe().Y, target.Y - 0.01, target.Y + 0.01);
            Assert.InRange(device.Observe().Z, target.Z - 0.01, target.Z + 0.01);
            await WaitAsync(() => Task.FromResult(device.Observe().InspectionStatus == 0 &&
                device.Observe().ZResetStatus is not (1 or 3)));
            var context = new InspectionHandshakeContext(runId, envelope.OperationId,
                result.ConnectionEpoch, target) { Role = role };
            await Assert.ThrowsAsync<InvalidOperationException>(async () =>
                await device.BeginInspectionAsync(context with { ConnectionEpoch = result.ConnectionEpoch + 1 }, default));
            await device.BeginInspectionAsync(context, default);
            Assert.Equal((ushort)1, (await observer.ReadRegistersAsync(
                O(ProtocolLatestMap.XyPositionConfirmed), 1))[0]);
            Assert.Equal((ushort)(role == "F" ? 3 : 1), (await observer.ReadRegistersAsync(
                O(ProtocolLatestMap.InspectionStatus), 1))[0]);
            await using (var rejection = new ModbusTcpClient("127.0.0.1", port, 1,
                TimeSpan.FromSeconds(1)))
                await Assert.ThrowsAsync<IOException>(() => rejection.WriteRegisterAsync(
                    O(ProtocolLatestMap.InspectionStatus), 0));
            Assert.Equal((ushort)(role == "F" ? 3 : 1), (await observer.ReadRegistersAsync(
                O(ProtocolLatestMap.InspectionStatus), 1))[0]);
            if (role == "F" && failFReset)
            {
                Assert.True(engine.InjectFault(SimulationFault.ZResetFailure).Accepted);
                await Assert.ThrowsAnyAsync<Exception>(async () =>
                    await device.CompleteInspectionAsync(context, TimeSpan.FromSeconds(5), default));
                return;
            }
            try { await device.CompleteInspectionAsync(context, TimeSpan.FromSeconds(5), default); }
            catch
            {
                output.WriteLine("InspectionFailure=" + JsonSerializer.Serialize(new
                {
                    role, device.Failure, observation = device.Observe(),
                    changes = store.GetChanges(0, 4096).Changes
                        .Where(change => change.Name is "Inspection_Status" or "Z_Reset_Status" or "XY_Move_Cmd")
                        .TakeLast(30),
                    writes = store.GetWriteAudit().TakeLast(30)
                }));
                throw;
            }
            Assert.Equal((ushort)0, (await observer.ReadRegistersAsync(
                O(ProtocolLatestMap.InspectionStatus), 1))[0]);
            Assert.Equal((ushort)1, (await observer.ReadRegistersAsync(
                O(ProtocolLatestMap.XyPositionConfirmed), 1))[0]);
        }
    }
    finally
    {
        await server.StopAsync(default);
        await engine.StopAsync(default);
        server.Dispose();
        engine.Dispose();
    }
}

