public async Task TcpProtocolExposesHeartbeatClampMoveSortUnloadUnlockAndFailureFacts()
{
    var port = FreePort();
    var simulation = new SimulationOptions
    {
        ScanPeriodMs = 2, HeartbeatPeriodMs = 20, HeartbeatTimeoutMs = 3000,
        MotionDurationMs = 12, SortingDurationMs = 12, PalletLockDurationMs = 12,
        ZoneConfigDurationMs = 8, InterActionGapMs = 4, ActionDurationJitterMs = 0,
        ZResetDurationMs = 8, ZResetTimeoutMs = 500, RandomSeed = 1
    };
    var store = new PlcDataStore(Options.Create(simulation));
    var engine = new VirtualPlcEngine(store, Options.Create(simulation),
        NullLogger<VirtualPlcEngine>.Instance);
    var server = new ModbusTcpServer(store, Options.Create(new ModbusOptions
    {
        ListenAddress = IPAddress.Loopback.ToString(), Port = port, UnitId = 1
    }), NullLogger<ModbusTcpServer>.Instance);
    await engine.StartAsync(default);
    await server.StartAsync(default);
    await WaitForPortAsync(port);
    await using var wire = new ModbusTcpClient("127.0.0.1", port, 1, TimeSpan.FromSeconds(1));
    await using var heartbeat = new ModbusTcpClient("127.0.0.1", port, 1, TimeSpan.FromSeconds(1));
    using var stop = new CancellationTokenSource();
    var echo = EchoHeartbeatAsync(heartbeat, stop.Token);
    try
    {
        await ChangedAsync(wire, O(ProtocolLatestMap.HeartbeatReq));
        await wire.WriteCoilAsync(O(ProtocolLatestMap.PcReady), true);

        await wire.WriteCoilAsync(O(ProtocolLatestMap.PcStart), true);
        await RegisterAsync(wire, ProtocolLatestMap.PalletLockStatus, 1);
        await wire.WriteCoilAsync(O(ProtocolLatestMap.PcStart), false);

        await wire.WriteRegistersAsync(O(ProtocolLatestMap.NgZoneCount), [15, 15]);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.ZoneConfigReady), 1);
        await RegisterAsync(wire, ProtocolLatestMap.ZoneConfigAck, 1);

        // Command 4 follows the completed inspection/Z-reset handshake and
        // performs a fresh XYZ move using Grab_Target_Z.
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetX, 11);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetY, 22);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetZ, 110);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.MoveCommand), 2);
        await RegisterAsync(wire, ProtocolLatestMap.XyPositionConfirmed, 1);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.MoveCommand), 0);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.InspectionStatus), 1);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.InspectionStatus), 2);
        await RegisterAsync(wire, ProtocolLatestMap.ZResetStatus, 2);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.InspectionStatus), 0);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetX, 11);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetY, 22);
        await WriteFloatAsync(wire, ProtocolLatestMap.GrabTargetZ, 150);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.MoveCommand), 4);
        await WaitAsync(async () => {
            var words = await wire.ReadRegistersAsync(O(ProtocolLatestMap.CurrentZ), 2);
            return ProtocolLatestFloat32.Decode(words[0], words[1],
                Gaode.Infrastructure.Devices.Plc.Float32ByteOrder.Abcd) == 150f;
        });
        await RegisterAsync(wire, ProtocolLatestMap.XyPositionConfirmed, 1);
        var actualZ = await wire.ReadRegistersAsync(O(ProtocolLatestMap.CurrentZ), 2);
        Assert.Equal(150f, ProtocolLatestFloat32.Decode(actualZ[0], actualZ[1],
            Gaode.Infrastructure.Devices.Plc.Float32ByteOrder.Abcd));
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.MoveCommand), 0);
        await RegisterAsync(wire, ProtocolLatestMap.XyPositionConfirmed, 1);

        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetX, 11);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetY, 22);
        await WriteFloatAsync(wire, ProtocolLatestMap.GrabTargetZ, 150);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortCommand), 1);
        await RegisterAsync(wire, ProtocolLatestMap.SortStatus, 2);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortCommand), 0);
        await Task.Delay(40);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortPartIndex), 3);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetX, 400);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetY, 300);
        await WriteFloatAsync(wire, ProtocolLatestMap.GrabTargetZ, 150);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortCommand), 2);
        await RegisterAsync(wire, ProtocolLatestMap.SortStatus, 3);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortCommand), 0);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortingOk), 1);
        await RegisterAsync(wire, ProtocolLatestMap.SortStatus, 0);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortingOk), 0);

        await wire.WriteRegisterAsync(O(ProtocolLatestMap.PalletLockCommand), 0);
        await RegisterAsync(wire, ProtocolLatestMap.PalletLockStatus, 0);

        await wire.WriteCoilAsync(O(ProtocolLatestMap.PcStart), true);
        await RegisterAsync(wire, ProtocolLatestMap.PalletLockStatus, 1);
        await wire.WriteCoilAsync(O(ProtocolLatestMap.PcStart), false);
        engine.InjectFault(SimulationFault.SortingFailure);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetX, 11);
        await WriteFloatAsync(wire, ProtocolLatestMap.CameraTargetY, 22);
        await WriteFloatAsync(wire, ProtocolLatestMap.GrabTargetZ, 150);
        await wire.WriteRegisterAsync(O(ProtocolLatestMap.SortCommand), 1);
        await RegisterAsync(wire, ProtocolLatestMap.SortStatus, 4);

        // A TCP session ending never manufactures a stage/business completion. A fresh
        // Modbus session observes the last PLC-owned physical facts verbatim.
        await using (var disconnected = new ModbusTcpClient(
            "127.0.0.1", port, 1, TimeSpan.FromSeconds(1)))
            _ = await disconnected.ReadRegistersAsync(O(ProtocolLatestMap.SortStatus), 1);
        await using var reconnected = new ModbusTcpClient("127.0.0.1", port, 1, TimeSpan.FromSeconds(1));
        Assert.Equal((ushort)1, (await reconnected.ReadRegistersAsync(
            O(ProtocolLatestMap.PalletLockStatus), 1))[0]);
        Assert.Equal((ushort)4, (await reconnected.ReadRegistersAsync(
            O(ProtocolLatestMap.SortStatus), 1))[0]);
        await reconnected.WriteRegisterAsync(O(ProtocolLatestMap.SortCommand), 0);
    }
    finally
    {
        stop.Cancel();
        try { await echo; } catch (OperationCanceledException) { }
        await server.StopAsync(default);
        await engine.StopAsync(default);
        server.Dispose();
        engine.Dispose();
    }
}

