public async Task InspectionHandshakeRunsOneWayAndClearsOnlyAfterResetSuccess()
{
    var (_, budget, profile) = TestConfiguration.Normal();
    var clock = new FakeTimeProvider(profile.VirtualStartUtc);
    using var plc = new SimulatedPlc(profile,
        new SimulationEventScheduler(clock, budget.Limits.MaxPendingTimerEvents),
        budget.BusinessMs.HeartbeatFlip);
    var events = new List<DeviceEventKind>();
    await plc.RequestStartAsync(Envelope(), Guid.NewGuid(), Guid.NewGuid(),
        e => events.Add(e.Kind), CancellationToken.None);
    clock.Advance(TimeSpan.FromMilliseconds(profile.Stages.PlcAcceptance.DelayMs));
    await Drain();
    clock.Advance(TimeSpan.FromMilliseconds(profile.Stages.ClampCompletion.DelayMs));
    await Drain();

    var move = new MoveRequest(Envelope(), Guid.NewGuid(),
        new("sim", "1.0.0", 100, 100, "mm", "SIM", 150),
        Guid.NewGuid(), "sim-plc", "3D");
    await plc.RequestMoveAsync(move, e => events.Add(e.Kind), CancellationToken.None);
    clock.Advance(TimeSpan.FromMilliseconds(profile.Stages.PlcAcceptance.DelayMs));
    await Drain();
    clock.Advance(TimeSpan.FromMilliseconds(profile.Stages.XyCompletion.DelayMs));
    await Drain();
    Assert.Equal(100, plc.Observe().X);

    var inspection = new InspectionHandshakeContext(move.Envelope.RunId,
        move.Envelope.OperationId, plc.Observe().ConnectionEpoch, move.Target);
    await plc.BeginInspectionAsync(inspection, CancellationToken.None);
    Assert.Equal(1, plc.Observe().InspectionStatus);
    await plc.CompleteInspectionAsync(inspection, TimeSpan.FromSeconds(1), CancellationToken.None);
    Assert.Equal(0, plc.Observe().InspectionStatus);
    Assert.Equal(2, plc.Observe().ZResetStatus);
}

