    Assert.Equal(HttpStatusCode.OK, allowed.StatusCode);
    Assert.Equal(Origin, Assert.Single(allowed.Headers.GetValues("Access-Control-Allow-Origin")));
    }
    finally
    {
        await server.StopAsync(default);
        await engine.StopAsync(default);
    }
}

